add(129,4,'Comparing two axes','supplied inertia comparison','medium',r'A thin uniform rod of mass $M$ and length $L$ has moment of inertia $ML^2/12$ about a perpendicular central axis and $ML^2/3$ about a parallel axis at one end. Equal resultant torques are applied about the two axes. What is the ratio $\alpha_{\rm centre}/\alpha_{\rm end}$?',options=[r'$4$',r'$1/4$',r'$2$',r'$1$'],reason=r'$\alpha=\tau/I$, so $\alpha_c/\alpha_e=I_e/I_c=(1/3)/(1/12)=4$.')
